dashboard.definition:
{
    "title": "Apotheke und Pflege",
    "description": "Krankenhausapotheke, Lieferengpaesse, Pflegepersonalbesetzung je Station und Lichtruf-Reaktionszeiten",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Abteilung",
            "options": {
                "items": [
                    {
                        "label": "Alle Abteilungen",
                        "value": "*"
                    },
                    {
                        "label": "Innere Medizin (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Kardiologie (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurologie (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Onkologie (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "Allgemeinchirurgie (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Unfallchirurgie/Orthopaedie (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urologie (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anaesthesie/OP (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensivmedizin (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Notaufnahme (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiologie (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynaekologie/Geburtshilfe (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Paediatrie (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatrie (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_stock": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:pharmacy\" type=stock earliest=-60m\n| stats latest(on_hand) as on_hand latest(reorder_point) as reorder_point latest(daily_usage) as daily_usage latest(days_of_supply) as days_of_supply latest(basg_shortage) as basg_shortage latest(status) as status latest(controlled) as controlled by atc drug",
                "enableSmartSources": true
            },
            "name": "Arzneimittelbestand"
        },
        "ds_k_crit": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_stock",
                "query": "| where status=\"kritisch\" | stats count as Kritisch"
            }
        },
        "ds_k_short": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_stock",
                "query": "| where basg_shortage=\"true\" OR basg_shortage=1 | stats count as Lieferengpass"
            }
        },
        "ds_stock_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_stock",
                "query": "| eval Engpass=if(basg_shortage=\"true\" OR basg_shortage=1, \"BASG-Meldung\", \"\"), BtM=if(controlled=\"true\" OR controlled=1, \"ja\", \"\")\n| sort days_of_supply | table drug atc on_hand reorder_point daily_usage days_of_supply Engpass BtM status\n| rename drug as Arzneimittel atc as ATC on_hand as Bestand reorder_point as Meldebestand daily_usage as \"Verbrauch/Tag\" days_of_supply as \"Reichweite (Tage)\" status as Status"
            }
        },
        "ds_dispense": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:pharmacy\" type=dispense department=\"$dept$\" | timechart span=1h sum(quantity) as Packungen by order_type",
                "enableSmartSources": true
            },
            "name": "Ausgaben"
        },
        "ds_top": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:pharmacy\" type=dispense department=\"$dept$\" | stats sum(quantity) as Packungen by drug | sort - Packungen | head 10 | rename drug as Arzneimittel",
                "enableSmartSources": true
            }
        },
        "ds_staff": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:nursing:staffing\" department=\"$dept$\" earliest=-35m\n| stats latest(shift) as shift latest(nurses_planned) as planned latest(nurses_present) as present latest(sick_leave) as sick latest(leasing) as leasing latest(patients) as patients latest(patients_per_nurse) as ratio latest(status) as status by ward department building",
                "enableSmartSources": true
            },
            "name": "Pflegebesetzung"
        },
        "ds_k_under": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_staff",
                "query": "| where status=\"unterbesetzt\" | stats count as Unterbesetzt"
            }
        },
        "ds_k_present": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_staff",
                "query": "| stats sum(present) as \"Pflegekraefte im Dienst\""
            }
        },
        "ds_k_sick": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_staff",
                "query": "| stats sum(sick) as Krankenstand"
            }
        },
        "ds_k_ratio": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.nursing.patients_per_nurse\" department=\"$dept$\" span=30m | rename v as \"Patienten je Pflegekraft\"",
                "enableSmartSources": true
            }
        },
        "ds_staff_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_staff",
                "query": "| sort - ratio | table ward department shift planned present sick leasing patients ratio status\n| rename ward as Station department as Abteilung shift as Dienst planned as Soll present as Ist sick as Krank leasing as Leasing patients as Patienten ratio as \"Pat./Pflegekraft\" status as Status"
            }
        },
        "ds_ratio_heat": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as value WHERE index=demo_sakh_metrics metric_name=\"sakh.nursing.patients_per_nurse\" department=\"$dept$\" BY ward span=30m\n| timechart span=30m limit=0 avg(value) by ward",
                "enableSmartSources": true
            }
        },
        "ds_call": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:nursecall\" department=\"$dept$\" | stats avg(response_s) as \"Reaktion (s)\" count as Rufe by ward | eval \"Reaktion (s)\"=round('Reaktion (s)', 0) | sort - \"Reaktion (s)\" | head 15 | rename ward as Station",
                "enableSmartSources": true
            }
        },
        "ds_call_type": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:nursecall\" department=\"$dept$\" | timechart span=1h count by call_type",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
