        "viz_07": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_stock_table"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 12,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Reichweite (Tage)": {
                        "rowBackgroundColors": "> table | seriesByName(\"Reichweite (Tage)\") | rangeValue(range_2)"
                    },
                    "Status": {
